--

CREATE TABLE `asset_lifecycle_events` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `asset_id` bigint(20) UNSIGNED NOT NULL,
  `event_type` enum('acquisition','deployment','transfer','maintenance','repair','upgrade','audit','warranty_expiry','depreciation','retirement','disposal','stolen','lost','found','damage','other') NOT NULL,
  `description` text DEFAULT NULL,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadata`)),
  `user_id` bigint(20) UNSIGNED DEFAULT NULL,
  `event_date` timestamp NOT NULL DEFAULT current_timestamp(),
  `ticket_id` bigint(20) UNSIGNED DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

